create table if not exists public.config_global_obraxis (id smallint primary key default 1 check (id = 1), nombre_plataforma text not null default 'Obraxis', url_publica text not null default 'https://www.obraxis.cl', correo_soporte text not null default 'soporte@obraxis.cl', pais text not null default 'Chile', zona_horaria text not null default 'America/Santiago', idioma text not null default 'es-CL', moneda text not null default 'CLP', correo_habilitado boolean not null default true, correo_remitente text not null default 'notificaciones@obraxis.cl', correo_respuesta text not null default 'soporte@obraxis.cl', hora_resumen_diario time not null default '18:00', ia_habilitada boolean not null default true, ia_proveedor text not null default 'OpenAI', ia_modelo text not null default 'gpt-4.1-mini', ia_confianza_minima smallint not null default 75 check (ia_confianza_minima between 0 and 100), ia_archivo_max_mb smallint not null default 10 check (ia_archivo_max_mb between 1 and 50), archivo_max_mb smallint not null default 25 check (archivo_max_mb between 1 and 100), retencion_documentos_anos smallint not null default 10 check (retencion_documentos_anos between 1 and 50), retencion_auditoria_anos smallint not null default 10 check (retencion_auditoria_anos between 1 and 50), modulos_empresa_nueva text not null default 'admin,obras', submenus_empresa_nueva text not null default '', mantenimiento_activo boolean not null default false, mensaje_mantenimiento text not null default 'Estamos realizando mejoras programadas. Intenta nuevamente en unos minutos.', actualizado_por text, updated_at timestamptz not null default now()); alter table public.config_global_obraxis enable row level security; revoke all on table public.config_global_obraxis from anon; grant select, insert, update on table public.config_global_obraxis to authenticated; create policy config_global_obraxis_select_admin on public.config_global_obraxis for select to authenticated using (private.obraxis_actor_can_manage_company('Obraxis')); create policy config_global_obraxis_insert_admin on public.config_global_obraxis for insert to authenticated with check (private.obraxis_actor_can_manage_company('Obraxis')); create policy config_global_obraxis_update_admin on public.config_global_obraxis for update to authenticated using (private.obraxis_actor_can_manage_company('Obraxis')) with check (private.obraxis_actor_can_manage_company('Obraxis')); insert into public.config_global_obraxis (id) values (1) on conflict (id) do nothing;;
